#!/usr/bin/env python3
"""Full verification of network state against definition of done."""
import json
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

DEVICES = {
    "HQ-Edge": {"host": "192.168.122.11", "device_type": "vyos", "username": "vyos", "password": "test"},
    "Hub-A":   {"host": "192.168.122.12", "device_type": "vyos", "username": "vyos", "password": "test"},
    "Hub-B":   {"host": "192.168.122.13", "device_type": "vyos", "username": "vyos", "password": "test"},
    "Branch-1": {"host": "192.168.122.21", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-2": {"host": "192.168.122.22", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-3": {"host": "192.168.122.23", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-4": {"host": "192.168.122.24", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
}

HOSTS = {
    "B1-PC1": {"host": "192.168.122.31", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.1.1.10"},
    "B1-PC2": {"host": "192.168.122.32", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.1.1.11"},
    "B2-PC1": {"host": "192.168.122.33", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.1.2.10"},
    "B2-PC2": {"host": "192.168.122.34", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.1.2.11"},
    "B3-PC1": {"host": "192.168.122.35", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.1.3.10"},
    "B3-PC2": {"host": "192.168.122.36", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.1.3.11"},
    "B4-PC1": {"host": "192.168.122.37", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.2.1.10"},
    "B4-PC2": {"host": "192.168.122.38", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.2.1.11"},
    "B4-PC3": {"host": "192.168.122.39", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.2.2.10"},
    "B4-PC4": {"host": "192.168.122.40", "device_type": "linux", "username": "root", "password": "alpine", "ip": "10.2.2.11"},
}

GUEST_HOSTS = {"B4-PC3", "B4-PC4"}
NON_GUEST_HOSTS = set(HOSTS.keys()) - GUEST_HOSTS


def collect_router(name, params):
    results = {}
    try:
        p = {k: v for k, v in params.items()}
        conn = ConnectHandler(**p)
        if params["device_type"] == "vyos":
            results["ospf_neighbors"] = conn.send_command("show ip ospf neighbor", read_timeout=15)
            results["routes"] = conn.send_command("show ip route", read_timeout=15)
            if name == "HQ-Edge":
                results["bgp_summary"] = conn.send_command("show ip bgp summary", read_timeout=15)
                results["bgp_table"] = conn.send_command("show ip bgp", read_timeout=15)
                results["bgp_adv_a"] = conn.send_command("show ip bgp neighbors 203.0.113.1 advertised-routes", read_timeout=15)
                results["bgp_adv_b"] = conn.send_command("show ip bgp neighbors 203.0.113.5 advertised-routes", read_timeout=15)
        else:
            results["ospf_neighbors"] = conn.send_command("/routing ospf neighbor print detail", read_timeout=15)
            results["routes"] = conn.send_command("/ip route print detail", read_timeout=15)
        conn.disconnect()
    except Exception as e:
        results["error"] = str(e)
    return name, results


def ping_from_host(host_name, params, targets):
    """Ping a list of targets from a host. Returns dict of target -> success."""
    results = {}
    try:
        p = {k: v for k, v in params.items() if k != "ip"}
        conn = ConnectHandler(**p)
        for target_name, target_ip in targets:
            try:
                out = conn.send_command(f"ping -c 2 -W 3 {target_ip}", read_timeout=15)
                results[target_name] = "0% packet loss" in out or "0.0% packet loss" in out or ", 0% loss" in out
                if not results[target_name]:
                    # check for at least 1 received
                    results[target_name] = " 1 packets received" in out or " 2 packets received" in out
            except Exception as e:
                results[target_name] = False
        conn.disconnect()
    except Exception as e:
        for target_name, _ in targets:
            results[target_name] = False
    return host_name, results


def main():
    print("=" * 60)
    print("VERIFICATION PASS")
    print("=" * 60)

    # 1. Collect router state
    print("\n--- Collecting router state ---")
    router_results = {}
    with ThreadPoolExecutor(max_workers=7) as pool:
        futures = []
        for name, params in DEVICES.items():
            futures.append(pool.submit(collect_router, name, params))
        for f in as_completed(futures):
            name, results = f.result()
            router_results[name] = results
            print(f"  [OK] {name}")

    # Print adjacencies
    print("\n--- ADJACENCIES ---")
