    # 2. Routing tables
    print("\n=== 2. ROUTING TABLES ===")
    for name in ["HQ-Edge", "Hub-A", "Hub-B", "Branch-1", "Branch-2", "Branch-3", "Branch-4"]:
        print(f"\n{name}:")
        print(router_data[name].get("routes", "N/A"))

    # 3. Host reachability - run serially per source to avoid conntrack interference
    print("\n=== 3. HOST REACHABILITY ===")
    all_host_ips = {name: info["ip"] for name, info in HOSTS.items()}

    # Non-guest to non-guest
    print("\nNon-guest to non-guest pings (56 pairs, should all PASS):")
    ng_pass = 0
    ng_fail = []
    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = []
        for src in sorted(NON_GUEST_HOSTS):
            for dst in sorted(NON_GUEST_HOSTS):
                if src != dst:
                    futures.append(pool.submit(ping_test, src, HOSTS[src], all_host_ips[dst], dst))
        for f in as_completed(futures):
            src, dst, ok = f.result()
            if ok:
                ng_pass += 1
            else:
                ng_fail.append(f"  FAIL: {src} -> {dst}")
    print(f"  {ng_pass}/56 passed")
    for fail in ng_fail:
        print(fail)

    # Guest to guest
    print("\nGuest to guest (should PASS):")
    for src in sorted(GUEST_HOSTS):
        for dst in sorted(GUEST_HOSTS):
            if src != dst:
                _, _, ok = ping_test(src, HOSTS[src], all_host_ips[dst], dst)
                print(f"  {src} -> {dst}: {'PASS' if ok else 'FAIL'}")

    # Guest <-> non-guest (should FAIL) - test serially to avoid conntrack issues
    print("\nGuest -> non-guest (should all FAIL - policy):")
    g_to_ng_correct = 0
    g_to_ng_wrong = []
    for src in sorted(GUEST_HOSTS):
        for dst in sorted(NON_GUEST_HOSTS):
            _, _, ok = ping_test(src, HOSTS[src], all_host_ips[dst], dst)
            if not ok:
                g_to_ng_correct += 1
            else:
                g_to_ng_wrong.append(f"  WRONG (should fail): {src} -> {dst}")
    print(f"  {g_to_ng_correct}/16 correctly blocked")
    for w in g_to_ng_wrong:
        print(w)

    print("\nNon-guest -> guest (should all FAIL - policy):")
    ng_to_g_correct = 0
    ng_to_g_wrong = []
    for src in sorted(NON_GUEST_HOSTS):
        for dst in sorted(GUEST_HOSTS):
            _, _, ok = ping_test(src, HOSTS[src], all_host_ips[dst], dst)
            if not ok:
                ng_to_g_correct += 1
            else:
                ng_to_g_wrong.append(f"  WRONG (should fail): {src} -> {dst}")
    print(f"  {ng_to_g_correct}/16 correctly blocked")
    for w in ng_to_g_wrong:
        print(w)

    # Internet
    print("\nInternet reachability:")
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for host in sorted(HOSTS.keys()):
            futures.append(pool.submit(ping_test, host, HOSTS[host], "8.8.8.8", "8.8.8.8"))
            futures.append(pool.submit(ping_test, host, HOSTS[host], "1.1.1.1", "1.1.1.1"))
        results = {}
        for f in as_completed(futures):
            src, tgt, ok = f.result()
            results.setdefault(src, {})[tgt] = ok
    for host in sorted(HOSTS.keys()):
        r = results.get(host, {})
        print(f"  {host}: 8.8.8.8={'PASS' if r.get('8.8.8.8') else 'FAIL'} 1.1.1.1={'PASS' if r.get('1.1.1.1') else 'FAIL'}")


if __name__ == "__main__":
    main()
